-- Demo content for the Temuraya marketing site.
-- Generated by scripts/demo/build-seed.mjs from scripts/demo/content.mjs; edit those, not this file.
-- Images are static files in public/demo/<theme>/ ("Sample N" placeholders).
-- Safe to re-run: replaces demo invitations only.

begin;

delete from public.invitations where is_demo;

-- Pernikahan Sekar & Damar (nusantara-ivory)
do $$
declare
  inv_id uuid;
begin
    type, title, slug, theme_id, status, event_date, venue_summary, package_key, is_demo,
    published_at, expires_at, cover_image_path, opening_quote, opening_message, closing_message, settings
  )
  select 'wedding', 'Pernikahan Sekar & Damar', 'demo-nusantara-ivory', t.id, 'published', '2027-05-15', 'Pendopo Sample, Yogyakarta',
    'grand', true, now(), null, '/demo/nusantara-ivory/cover.jpg',
    'Dan di antara tanda-tanda kekuasaan-Nya ialah Dia menciptakan untukmu pasangan dari jenismu sendiri, supaya kamu merasa tenteram kepadanya. (QS. Ar-Rum: 21)', 'Dengan memohon rahmat Tuhan Yang Maha Esa, kami mengundang Bapak/Ibu/Saudara/i untuk hadir dan memberikan doa restu pada hari bahagia kami.', 'Merupakan suatu kehormatan dan kebahagiaan bagi kami apabila Bapak/Ibu/Saudara/i berkenan hadir. Terima kasih atas doa dan restunya.', '{"features":{"music":false,"countdown":true,"maps":true,"story":true,"gallery":true,"dressCode":true,"livestream":true,"rsvp":true,"wishes":true,"gift":true,"guestPersonalization":true},"timeZone":"Asia/Jakarta","dressCode":{"description":"Busana batik atau kebaya dengan nuansa hangat.","groups":[{"label":"Tamu","colors":["#A87A3D","#E9DCC4","#2F4A3A"]}]}}'::jsonb
  from public.themes t where t.slug = 'nusantara-ivory'
  returning id into inv_id;






end $$;

update public.themes set
  tagline = 'Editorial Nusantara yang tenang, gading dan emas.',
  description = 'Nuansa gading dengan aksen emas dan detail Nusantara yang halus. Pembuka dengan melati yang berguguran, tipografi klasik, dan tata letak bergaya majalah.

Cocok untuk akad dan resepsi adat yang ingin tampil anggun dan bersahaja.',
  event_types = array['wedding']::text[],
  screenshot_paths = array['/demo/nusantara-ivory/screen-1.jpg', '/demo/nusantara-ivory/screen-2.jpg', '/demo/nusantara-ivory/screen-3.jpg']::text[],
  sort_order = 1,
  is_listed = true
where slug = 'nusantara-ivory';

